async function fetchEnvironments(): Promise<EnvironmentSummary[]> {
  const environments = await listEnvironments();
  return environments.map((item) => ({
    id: item.id, name: item.name, description: item.spec.nodes.map((node) => node.roles.join(", ")).filter(Boolean).join(" · ") || "Draft environment",
    lifecycle: item.lifecycle,
    health: item.health, region: item.spec.region, nodes: item.spec.nodes.length,
    workloads: item.spec.deployments.length, observedAt: item.updatedAt, expiresAt: item.expiresAt ?? undefined
  }));
}

function healthTone(health: string) {
  return health === "healthy" || health === "online" ? "success" as const : health === "degraded" ? "warning" as const : health === "unreachable" || health === "offline" ? "danger" as const : "neutral" as const;
}

export function EnvironmentsPage() {
  const { data, isLoading, error } = useQuery({ queryKey: ["environments"], queryFn: fetchEnvironments });
  const [query, setQuery] = useState("");
  const columns = useMemo<ColumnDef<EnvironmentSummary>[]>(() => [
    { accessorKey: "name", header: "Environment", cell: ({ row }) => <Link className="primary-cell" to={`/environments/${row.original.id}`}><span className="resource-avatar"><Network /></span><span><strong>{row.original.name}</strong><small>{row.original.description}</small></span></Link> },
    { accessorKey: "health", header: "Health", cell: ({ getValue }) => <StatusBadge tone={healthTone(String(getValue()))}>{String(getValue())}</StatusBadge> },
    { accessorKey: "region", header: "Region", cell: ({ getValue }) => <span className="mono">{String(getValue())}</span> },
    { id: "resources", header: "Resources", cell: ({ row }) => <span>{row.original.nodes} nodes · {row.original.workloads} workloads</span> },
    { accessorKey: "observedAt", header: "Observed", cell: ({ getValue }) => <time title={new Date(String(getValue())).toISOString()} dateTime={String(getValue())}>{relativeTime(String(getValue()))}</time> },
    { id: "open", header: "", cell: ({ row }) => <Link className="row-action" to={`/environments/${row.original.id}`} aria-label={`Open ${row.original.name}`}><ChevronRight /></Link> }
  ], []);
  const rows = (data ?? []).filter((environment) => `${environment.name} ${environment.description} ${environment.region}`.toLowerCase().includes(query.toLowerCase()));
  const activeCount = data?.filter((environment) => environment.lifecycle === "active" || environment.lifecycle === "applying").length ?? 0;
  const attentionCount = data?.filter((environment) => ["degraded", "unreachable"].includes(environment.health) || environment.lifecycle.endsWith("failed")).length ?? 0;
  const resourceCount = data?.reduce((total, environment) => total + environment.nodes + environment.workloads, 0) ?? 0;
  const nextExpiry = data?.flatMap((environment) => environment.expiresAt ? [{ name: environment.name, date: environment.expiresAt }] : []).sort((a, b) => a.date.localeCompare(b.date))[0];
  const table = useReactTable({ data: rows, columns, getCoreRowModel: getCoreRowModel() });
  return <div className="page">
    <PageHeader title="Environments" description="Plan, operate, and retire engagement infrastructure from one place." action={<ButtonLink to="/environments/new" icon={Plus}>New environment</ButtonLink>} />
    <section className="summary-strip" aria-label="Environment summary">
      <div><span>Active</span><strong>{isLoading ? "—" : activeCount}</strong><small>{isLoading ? "Loading" : `${data?.filter((environment) => environment.lifecycle === "applying").length ?? 0} applying`}</small></div><div><span>Attention</span><strong className="text-warning">{isLoading ? "—" : attentionCount}</strong><small>{attentionCount ? "Review degraded environments" : "No known issues"}</small></div><div><span>Desired resources</span><strong>{isLoading ? "—" : resourceCount}</strong><small>{data?.length ? `Across ${new Set(data.map((item) => item.region)).size} regions` : "No environments"}</small></div><div><span>Next expiry</span><strong>{nextExpiry ? relativeTime(nextExpiry.date) : "None"}</strong><small>{nextExpiry ? `${nextExpiry.name} · ${new Date(nextExpiry.date).toLocaleDateString()}` : "No expiry scheduled"}</small></div>
    </section>
    <div className="toolbar"><label className="search-field"><Search /><span className="sr-only">Search environments</span><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search by name, role, or region" /></label></div>
    {isLoading ? <section className="panel"><Skeleton rows={6} /></section> : error ? <IssueBanner tone="danger" title="Environments could not be loaded">{error instanceof ApiError ? error.detail ?? error.message : "Refresh the page or check the control-plane connection."}</IssueBanner> : rows.length === 0 ? <EmptyState icon={Search} title="No environments match" detail="Try a broader search, or create a new environment." /> : <div className="table-shell"><table><thead>{table.getHeaderGroups().map((group) => <tr key={group.id}>{group.headers.map((header) => <th key={header.id}>{flexRender(header.column.columnDef.header, header.getContext())}</th>)}</tr>)}</thead><tbody>{table.getRowModel().rows.map((row) => <tr key={row.id}>{row.getVisibleCells().map((cell) => <td key={cell.id}>{flexRender(cell.column.columnDef.cell, cell.getContext())}</td>)}</tr>)}</tbody></table></div>}
    {demoMode ? <p className="demo-note"><Info /> Simulated mode uses deterministic product data and never calls the control plane.</p> : null}
  </div>;
}

const environmentSchema = Type.Object({ name: Type.String({ minLength: 2 }), region: Type.String(), expiresAt: Type.Optional(Type.String()) });
type EnvironmentForm = { name: string; region: string; expiresAt?: string };

export function CreateEnvironmentPage() {
  const [step, setStep] = useState(1);
  const [blueprint, setBlueprint] = useState<"single" | "segmented">("segmented");
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);
  const navigate = useNavigate();
  const { register, watch, formState: { errors }, trigger } = useForm<EnvironmentForm>({ defaultValues: { name: "", region: "eu-west-1", expiresAt: "" } });
  const values = watch();
  const selectedBlueprint = (blueprint === "single" ? singleNodeBlueprint : segmentedBlueprint) as unknown as { id: string; version: number; name: string; description: string; spec: EnvironmentSpec };
  const next = async () => { if (step === 1 && !(await trigger(["name", "region"]))) return; setStep(Math.min(5, step + 1)); };
  const createDraftAndPlan = async () => {
    setSubmitting(true); setSubmitError(null);
    const spec: EnvironmentSpec = { ...structuredClone(selectedBlueprint.spec), name: values.name, region: values.region, ...(values.expiresAt ? { expiresAt: new Date(values.expiresAt).toISOString() } : {}) };
    try {
      const environment = await createEnvironment(spec);
      const operation = await startPlan(environment.id);
      navigate(`/environments/${environment.id}/plan?operationId=${operation.id}`, { state: { environment, operation } });
    } catch (error) {
      setSubmitError(error instanceof ApiError ? error.detail ?? error.message : "The draft could not be created.");
    } finally { setSubmitting(false); }
  };
  const steps = ["Basics", "Blueprint", "Infrastructure", "Workloads", "Review"];
  return <div className="page page--narrow">
    <Link to="/environments" className="back-link"><ArrowLeft /> Environments</Link>
    <PageHeader eyebrow={`Step ${step} of ${steps.length}`} title="Create environment" description="Start from an opinionated blueprint, then review every resource before anything changes." />
    <ol className="stepper" aria-label="Creation progress">{steps.map((name, index) => <li key={name} className={index + 1 === step ? "active" : index + 1 < step ? "complete" : ""}><span>{index + 1 < step ? <Check /> : index + 1}</span><small>{name}</small></li>)}</ol>
    <section className="form-surface">
      {step === 1 ? <div className="form-section"><h2>Name and location</h2><p>Give this environment a recognizable engagement name.</p><label className="field"><span>Name</span><input autoFocus {...register("name", { required: "Enter an environment name", minLength: { value: 2, message: "Use at least two characters" } })} placeholder="e.g. Nightfall" />{errors.name ? <small className="field-error">{errors.name.message}</small> : <small>Visible throughout the operator console.</small>}</label><div className="field-row"><label className="field"><span>AWS region</span><select {...register("region", { required: true })}><option value="eu-west-1">Europe (Ireland)</option><option value="eu-central-1">Europe (Frankfurt)</option><option value="us-east-1">US East (N. Virginia)</option><option value="us-west-2">US West (Oregon)</option></select></label><label className="field"><span>Automatic expiry <em>Optional</em></span><input type="datetime-local" {...register("expiresAt")} /><small>Expiry starts the reviewed destroy workflow.</small></label></div></div> : null}
      {step === 2 ? <div className="form-section"><h2>Choose a starting point</h2><p>The versioned blueprint JSON is copied into this first immutable revision.</p><div className="choice-grid"><button className={`choice-card ${blueprint === "single" ? "selected" : ""}`} onClick={() => setBlueprint("single")}><span className="choice-card__icon"><Server /></span><span><strong>{singleNodeBlueprint.name}</strong><small>{singleNodeBlueprint.description}</small></span>{blueprint === "single" ? <CheckCircle2 /> : <Circle />}</button><button className={`choice-card ${blueprint === "segmented" ? "selected" : ""}`} onClick={() => setBlueprint("segmented")}><span className="choice-card__icon"><Network /></span><span><strong>{segmentedBlueprint.name}</strong><small>{segmentedBlueprint.description}</small></span>{blueprint === "segmented" ? <CheckCircle2 /> : <Circle />}</button></div><IssueBanner tone="info" title={`Blueprint version ${selectedBlueprint.version}`}>The copied specification remains independent after creation. Later changes require a reviewed revision.</IssueBanner></div> : null}
      {step === 3 ? <div className="form-section"><h2>Blueprint infrastructure</h2><p>The selected blueprint defines this first revision. These resources are read-only in the creation flow.</p><div className="resource-stack">{selectedBlueprint.spec.nodes.map((node) => <ResourceRow key={node.key} icon={node.source.kind === "aws" ? Cloud : Laptop} title={node.name} detail={node.source.kind === "aws" ? `AWS · ${node.source.instanceType} · ${node.source.publicEndpoint ? "Public endpoint" : "No public endpoint"} · ${node.roles.join(", ")}` : `Adopted host · ${node.roles.join(", ")}`} badge={node.source.kind === "aws" ? "Managed" : "Adopted"} />)}</div><IssueBanner tone="info" title="Desired infrastructure only">Actual AWS resource counts are calculated later by the provider-backed plan.</IssueBanner></div> : null}
      {step === 4 ? <div className="form-section"><h2>Workload deployment</h2><p>This draft starts without workloads. Publish restricted workload versions in the catalog, then add them through a reviewed environment revision.</p><EmptyState icon={Package} title="No workloads in this revision" detail="Creating an empty environment keeps this first apply focused on infrastructure and host enrollment." action={<ButtonLink to="/workloads/import" variant="secondary" icon={Upload}>Import a workload separately</ButtonLink>} /></div> : null}
      {step === 5 ? <div className="form-section"><h2>Review draft</h2><p>No infrastructure is created until you generate and apply a plan.</p><DefinitionList items={[["Environment", values.name || selectedBlueprint.spec.name], ["Region", values.region], ["Blueprint", `${selectedBlueprint.name} · version ${selectedBlueprint.version}`], ["Nodes", `${selectedBlueprint.spec.nodes.filter((node) => node.source.kind === "aws").length} managed · ${selectedBlueprint.spec.nodes.filter((node) => node.source.kind === "adopted").length} adopted`], ["Workloads", `${selectedBlueprint.spec.deployments.length} in this revision`], ["Private network", selectedBlueprint.spec.network.cidr]]} /></div> : null}
      {submitError ? <IssueBanner tone="danger" title="Draft could not be created">{submitError}</IssueBanner> : null}
      <footer className="form-footer"><Button variant="quiet" onClick={() => step === 1 ? navigate("/environments") : setStep(step - 1)}>{step === 1 ? "Cancel" : "Back"}</Button>{step < 5 ? <Button onClick={next}>Continue <ArrowRight /></Button> : <Button onClick={createDraftAndPlan} disabled={submitting}>{submitting ? "Creating draft…" : "Create draft and plan"} <FileDiff /></Button>}</footer>
    </section>
    <span className="sr-only">Form schema version {environmentSchema.type === "object" ? "1" : "unknown"}</span>
  </div>;
}

function ResourceRow({ icon: Icon, title, detail, badge }: { icon: typeof Cloud; title: string; detail: string; badge: string }) {
  return <div className="resource-row"><span className="resource-avatar"><Icon /></span><span><strong>{title}</strong><small>{detail}</small></span><StatusBadge tone="neutral">{badge}</StatusBadge></div>;
}

export function EnvironmentOverviewPage() {
  const { environment } = useOutletContext<EnvironmentOutletContext>();
  const fallback = environmentById(environment.id);
  const env: EnvironmentSummary = demoMode ? { ...fallback, id: environment.id, name: environment.name, lifecycle: environment.lifecycle, health: environment.health, region: environment.spec.region, nodes: environment.spec.nodes.length, workloads: environment.spec.deployments.length, observedAt: environment.updatedAt, expiresAt: environment.expiresAt ?? undefined } : { id: environment.id, name: environment.name, description: "", lifecycle: environment.lifecycle, health: environment.health, region: environment.spec.region, nodes: environment.spec.nodes.length, workloads: environment.spec.deployments.length, observedAt: environment.updatedAt, expiresAt: environment.expiresAt ?? undefined };
  const visibleNodes = demoMode ? demoNodes : environment.spec.nodes.map((node, index) => ({ id: node.key, name: node.name, role: node.roles.join(", ") || "Unassigned", origin: node.source.kind === "aws" ? "AWS managed" : "Adopted", health: "unknown", overlay: `Pending allocation`, publicAddress: node.source.kind === "aws" && node.source.publicEndpoint ? "Pending allocation" : "Private", observedAt: environment.updatedAt }));
  return <div className="environment-body">
    {env.lifecycle === "apply_failed" ? <IssueBanner tone="danger" title="The latest apply failed" actions={<ButtonLink to={`/environments/${env.id}/plan`} icon={RefreshCw}>Refresh and plan recovery</ButtonLink>}>{demoMode ? "The simulated workload health check did not pass." : "Actual state may be partial or unknown. Refresh provider state before deciding whether to retry or destroy."}</IssueBanner> : env.activeOperation ? <IssueBanner tone="info" title="Environment is changing" actions={<ButtonLink to={`/environments/${env.id}/operation`} variant="secondary">View operation</ButtonLink>}>{env.activeOperation.title} · step {env.activeOperation.step} of {env.activeOperation.total}</IssueBanner> : null}
    <section className="hero-status"><div><p className="eyebrow">Environment health</p><div className="hero-status__value"><span className={`health-orb health-orb--${env.health}`}><ShieldCheck /></span><span><strong>{env.health === "healthy" ? "Everything is ready" : env.health === "degraded" ? "Action is required" : "State is unknown"}</strong><small>Record updated {relativeTime(env.observedAt)} · <time>{new Date(env.observedAt).toLocaleString()}</time></small></span></div></div><div className="hero-actions"><ButtonLink to={`/environments/${env.id}/plan`} icon={FileDiff}>Refresh and plan changes</ButtonLink></div></section>
    <div className="two-column"><section><SectionHeader title="Topology" detail="Public and private relationships" action={<Link to="nodes">View nodes</Link>} /><div className="topology"><div className="topology-public"><small>Public edge</small>{visibleNodes.filter((node) => node.origin === "AWS managed").map((node) => <TopologyNode key={node.id} icon={Cloud} title={node.name} detail={`${node.role} · ${node.publicAddress}`} state={node.health === "online" ? "healthy" : "unknown"} />)}</div><div className="topology-link"><span /><small>Nebula · {environment.spec.network.cidr}</small><span /></div><div className="topology-private"><small>Private network</small>{visibleNodes.filter((node) => node.origin === "Adopted").map((node) => <TopologyNode key={node.id} icon={Laptop} title={node.name} detail={`${node.role} · ${node.overlay}`} state={node.health === "degraded" ? "warning" : "unknown"} />)}</div></div></section><section><SectionHeader title="Environment facts" detail="Desired and observed state" /><div className="panel"><DefinitionList items={[["Lifecycle", <StatusBadge tone={env.lifecycle === "active" ? "success" : "warning"}>{env.lifecycle.replace("_", " ")}</StatusBadge>], ["Revision", `${environment.desiredRevision} desired · ${environment.appliedRevision ?? "not applied"}`], ["AWS region", <span className="mono">{env.region}</span>], ["Nodes", `${env.nodes} desired`], ["Workloads", `${env.workloads} desired`], ["Expiry", env.expiresAt ? new Date(env.expiresAt).toLocaleString() : "None"]]} /></div></section></div>
    <SectionHeader title="Recent activity" detail="Meaningful changes across this environment" action={<Link to="activity">View all</Link>} />{demoMode ? <ActivityList compact /> : <EmptyState icon={Icons.Activity} title="No recent activity" detail="Operations and observations will appear here as they are persisted." />}
  </div>;
}

function SectionHeader({ title, detail, action }: { title: string; detail?: string; action?: React.ReactNode }) { return <div className="section-header"><div><h2>{title}</h2>{detail ? <p>{detail}</p> : null}</div>{action}</div>; }
function TopologyNode({ icon: Icon, title, detail, state }: { icon: typeof Cloud; title: string; detail: string; state: string }) { return <div className="topology-node"><span className="resource-avatar"><Icon /></span><span><strong>{title}</strong><small>{detail}</small></span><span className={`state-dot state-dot--${state}`} /></div>; }

export function NodesPage() {
  const [selected, setSelected] = useState<string | null>(null);
  const { environment } = useOutletContext<EnvironmentOutletContext>();
  const nodeQuery = useQuery({ queryKey: ["nodes", environment.id], queryFn: () => listNodes(environment.id), enabled: !demoMode, refetchInterval: 15_000 });
  const observedByKey = new Map((nodeQuery.data ?? []).map((node) => [node.nodeKey, node]));
  const nodes = demoMode ? demoNodes.map((node) => ({ ...node, lifecycle: "active", raw: node })) : environment.spec.nodes.map((node) => {
    const observed = observedByKey.get(node.key);
    return { id: observed?.id ?? node.key, name: node.name, role: node.roles.join(", ") || "Unassigned", origin: node.source.kind === "aws" ? "AWS managed" as const : "Adopted" as const, health: observed?.health ?? "unknown", lifecycle: observed?.lifecycle ?? "pending", overlay: "Not reported", publicAddress: "Not reported", observedAt: observed?.lastSeenAt ?? "", raw: observed ?? { nodeKey: node.key, desired: true, observation: null } };
  });
  const selectedNode = nodes.find((node) => node.id === selected);
  const observedCount = demoMode ? nodes.length : nodes.filter((node) => node.observedAt).length;
  const inspectorDetails: [string, ReactNode][] = selectedNode ? [["Health", <StatusBadge tone={healthTone(selectedNode.health)}>{selectedNode.health}</StatusBadge>], ["Lifecycle", selectedNode.lifecycle], ["Origin", selectedNode.origin], ["Overlay address", selectedNode.overlay], ["Last heartbeat", selectedNode.observedAt ? relativeTime(selectedNode.observedAt) : "Never reported"]] : [];
  return <div className="environment-body with-inspector"><div className="content-column"><SectionHeader title="Nodes" detail="Desired machines and their latest persisted state" action={<ButtonLink to={`/environments/${environment.id}/adopt`} variant="secondary" icon={Plus}>Adopt host</ButtonLink>} />{!demoMode && nodeQuery.error ? <IssueBanner tone="danger" title="Node observations could not be loaded">{nodeQuery.error instanceof Error ? nodeQuery.error.message : "The node inventory is unavailable."}</IssueBanner> : !demoMode && !nodeQuery.isLoading && observedCount < nodes.length ? <IssueBanner tone="info" title={observedCount ? "Some nodes have not reported" : "No node observations yet"}>{observedCount} of {nodes.length} desired nodes have a persisted heartbeat. Missing observations remain unknown.</IssueBanner> : null}{nodeQuery.isLoading && !demoMode ? <Skeleton rows={nodes.length || 3} /> : <div className="resource-list">{nodes.map((node) => <button key={node.id} className="resource-list__row" onClick={() => setSelected(node.id)}><span className="resource-avatar">{node.origin === "Adopted" ? <Laptop /> : <Cloud />}</span><span className="resource-list__name"><strong>{node.name}</strong><small>{node.role} · {node.origin}</small></span><span className="resource-list__address"><small>Overlay</small><span className="mono">{node.overlay}</span></span><span><StatusBadge tone={healthTone(node.health)}>{node.health}</StatusBadge></span><span className="resource-list__observed"><small>Heartbeat</small>{node.observedAt ? relativeTime(node.observedAt) : "Never"}</span><ChevronRight /></button>)}</div>}</div><Inspector open={Boolean(selectedNode)} title={selectedNode?.name ?? "Node"} details={inspectorDetails} raw={selectedNode?.raw ?? null} activity={selectedNode?.observedAt ? `Latest heartbeat ${relativeTime(selectedNode.observedAt)}.` : "No heartbeat has been persisted for this node."} onClose={() => setSelected(null)} /></div>;
}

export function EnvironmentWorkloadsPage() { const { environment } = useOutletContext<EnvironmentOutletContext>(); const workloads = demoMode ? demoWorkloads : environment.spec.deployments.map((deployment) => ({ id: deployment.key, name: deployment.key, version: deployment.workloadVersionId.slice(0, 8), node: deployment.nodeKey, health: "stopped" as const, endpoint: deployment.exposures.length ? deployment.exposures.map((item) => `${item.protocol.toUpperCase()}/${item.port}`).join(", ") : "Overlay only" })); return <div className="environment-body"><SectionHeader title="Workloads" detail="Versioned deployments pinned to environment nodes" />{workloads.length === 0 ? <EmptyState title="No workloads configured" detail="This desired revision contains no workload deployments. Additions require a new reviewed specification revision." action={<ButtonLink to="/workloads" variant="secondary">Browse published workloads</ButtonLink>} /> : <div className="resource-list">{workloads.map((workload) => <div key={workload.id} className="resource-list__row resource-list__row--static"><span className="resource-avatar"><Package /></span><span className="resource-list__name"><strong>{workload.name}</strong><small>Version {workload.version} · {workload.node}</small></span><span className="resource-list__address"><small>Endpoint</small><span>{workload.endpoint}</span></span><StatusBadge tone={healthTone(workload.health)}>{workload.health}</StatusBadge></div>)}</div>}</div>; }
export function EnvironmentActivityPage() { return <div className="environment-body"><SectionHeader title="Activity" detail="Durable operation history and significant observations" />{demoMode ? <ActivityList /> : <EmptyState icon={Icons.Activity} title="No activity yet" detail="The control plane has not reported any environment activity." />}</div>; }

function ActivityList({ compact = false }: { compact?: boolean }) { return <div className="activity-list">{activity.slice(0, compact ? 3 : undefined).map((item) => <div className="activity-item" key={item.id}><span className={`activity-icon activity-icon--${item.type}`}>{item.type === "success" ? <Check /> : item.type === "danger" ? <XCircle /> : <Circle />}</span><span><strong>{item.title}</strong><small>{item.environment}</small></span><time dateTime={item.at} title={new Date(item.at).toISOString()}>{relativeTime(item.at)}</time></div>)}</div>; }

export function EnvironmentSettingsPage() {
  const { environment } = useOutletContext<EnvironmentOutletContext>();
  return <div className="environment-body"><SectionHeader title="Environment settings" detail="Lifecycle policy and control boundaries" /><section className="settings-section"><div><h3>Automatic expiry</h3><p>{environment.expiresAt ? `Scheduled for ${new Date(environment.expiresAt).toLocaleString()}.` : "No automatic expiry is set in the current specification."}</p></div><StatusBadge tone={environment.expiresAt ? "info" : "neutral"}>{environment.expiresAt ? "Scheduled" : "Not set"}</StatusBadge></section><section className="settings-section"><div><h3>Agent observations</h3><p>Online agents send a heartbeat every 15 seconds and a full observation every 60 seconds. These runtime defaults are fixed in this release.</p></div><StatusBadge tone="neutral">60 seconds</StatusBadge></section><IssueBanner tone="info" title="Changes create a new revision">Expiry, nodes, roles, and deployments are immutable in revision {environment.desiredRevision}. A specification editor will create a new reviewed revision rather than mutating this one.</IssueBanner><section className="danger-zone"><div><h3>End environment</h3><p>Review the known desired scope, confirm residual risk, and then start a durable destroy operation.</p></div><ButtonLink to={`/environments/${environment.id}/destroy`} variant="danger" icon={Trash2}>Review destruction</ButtonLink></section></div>;
}

export function PlanPage() {
  const { environmentId = "" } = useParams(); const fallbackEnv = environmentById(environmentId); const [ack, setAck] = useState(false); const navigate = useNavigate();
  const [searchParams] = useSearchParams(); const location = useLocation();
  const routeState = location.state as { environment?: { name: string; spec: { region: string } }; operation?: Operation } | null;
  const planOperationId = searchParams.get("operationId") ?? routeState?.operation?.id;
  const autoPlanStarted = useRef(false); const [autoPlanError, setAutoPlanError] = useState<string | null>(null);
  useEffect(() => { if (planOperationId || !environmentId || autoPlanStarted.current) return; autoPlanStarted.current = true; void startPlan(environmentId).then((operation) => navigate(`/environments/${environmentId}/plan?operationId=${operation.id}`, { replace: true, state: routeState })).catch((error: unknown) => setAutoPlanError(error instanceof ApiError ? error.detail ?? error.message : "Planning could not be started.")); }, [environmentId, navigate, planOperationId]);
  const operationQuery = useQuery({
    queryKey: ["operation", planOperationId], queryFn: () => getOperation(planOperationId!), enabled: Boolean(planOperationId), initialData: routeState?.operation,
    refetchInterval: (query) => query.state.data && ["queued", "running", "waiting"].includes(query.state.data.state) ? 1000 : false
  });
  const environmentQuery = useQuery({ queryKey: ["environment", environmentId], queryFn: () => getEnvironment(environmentId), enabled: Boolean(environmentId) && !routeState?.environment });
  const [applying, setApplying] = useState(false); const [applyError, setApplyError] = useState<string | null>(null);
  const rawResult = operationQuery.data?.result;
  const planCandidate = rawResult && "plan" in rawResult ? rawResult.plan : rawResult;
  const plan = Value.Check(PlanArtifactSchema, planCandidate) ? planCandidate as PlanArtifact : undefined;
  const isPlanning = Boolean(planOperationId) && (!operationQuery.data || ["queued", "running", "waiting"].includes(operationQuery.data.state));
  const env = { name: routeState?.environment?.name ?? environmentQuery.data?.name ?? (demoMode ? fallbackEnv.name : "Environment"), region: routeState?.environment?.spec.region ?? environmentQuery.data?.spec.region ?? plan?.region ?? (demoMode ? fallbackEnv.region : "Unknown") };
  const changes = plan?.changes.map((change) => ({ action: change.action, symbol: change.action === "create" ? "+" : change.action === "delete" ? "−" : change.action === "same" ? "·" : "~", tone: change.action === "create" ? "add" : change.action === "delete" || change.action === "replace" ? "delete" : change.action === "same" ? "neutral" : "change", title: change.resourceKey, detail: change.summary, group: change.resourceType.toLowerCase().includes("workload") ? "Workloads" : change.resourceType.toLowerCase().includes("node") ? "Nodes" : "Infrastructure" })) ?? [];
  const stale = Boolean(plan && new Date(plan.expiresAt).getTime() <= Date.now());
  const planFailed = operationQuery.data && ["failed", "blocked", "needs_reconciliation", "cancelled"].includes(operationQuery.data.state);
  const applyPlan = async () => {
    if (!planOperationId) { setApplyError("Generate a plan before applying this environment."); return; }
    setApplying(true); setApplyError(null);
    try { const operation = await startApply(environmentId, planOperationId); navigate(`/environments/${environmentId}/operation?operationId=${operation.id}`, { state: { operation, environment: routeState?.environment } }); }
    catch (error) { setApplyError(error instanceof ApiError ? error.detail ?? error.message : "Apply could not be started."); }
    finally { setApplying(false); }
  };
  if (!planOperationId && !autoPlanError) return <div className="page page--wide"><Link to={`/environments/${environmentId}`} className="back-link"><ArrowLeft /> {env.name}</Link><PageHeader eyebrow="Plan operation" title="Starting provider refresh" description="No infrastructure is changing." /><section className="waiting-card"><span className="waiting-orb"><RefreshCw className="spin" /></span><h2>Starting plan</h2><p>This page will continue when the durable planning operation is created.</p></section></div>;
  if (autoPlanError) return <div className="page page--wide"><IssueBanner tone="danger" title="Planning could not be started">{autoPlanError}</IssueBanner></div>;
  if (isPlanning) return <div className="page page--wide"><Link to={`/environments/${environmentId}`} className="back-link"><ArrowLeft /> {env.name}</Link><PageHeader eyebrow="Plan operation" title="Refreshing actual state" description="Infractory is observing the provider before calculating a trustworthy diff." /><section className="waiting-card"><span className="waiting-orb"><RefreshCw className="spin" /></span><h2>Generating plan</h2><p>This page updates automatically. No infrastructure is changing.</p></section></div>;
  if (operationQuery.error) return <div className="page page--wide"><IssueBanner tone="danger" title="Plan could not be loaded">{operationQuery.error instanceof ApiError ? operationQuery.error.detail ?? operationQuery.error.message : "The plan operation is unavailable."}</IssueBanner></div>;
  if (planFailed && !plan) { const failedStep = operationQuery.data?.steps.find((step) => step.state === "failed"); return <div className="page page--wide"><Link to={`/environments/${environmentId}`} className="back-link"><ArrowLeft /> {env.name}</Link><IssueBanner tone="danger" title={`Planning ${operationQuery.data?.state.replaceAll("_", " ")}`}>{failedStep?.errorMessage ?? "The control plane did not produce an applicable plan. Review the operation details before trying again."}</IssueBanner>{operationQuery.data ? <ButtonLink to={`/environments/${environmentId}/operation?operationId=${operationQuery.data.id}`} variant="secondary">Review operation</ButtonLink> : null}</div>; }
  if (!demoMode && planOperationId && operationQuery.data?.state === "succeeded" && !plan) return <div className="page page--wide"><IssueBanner tone="danger" title="Plan result is invalid">The control plane completed planning but did not return a valid plan artifact. Apply is blocked.</IssueBanner></div>;
  return <div className="page page--wide"><Link to={`/environments/${environmentId}`} className="back-link"><ArrowLeft /> {env.name}</Link><PageHeader eyebrow={`Revision ${plan?.revision ?? "unknown"}`} title="Review plan" description="Confirm the exact desired changes before Infractory touches external infrastructure." action={<StatusBadge tone={stale || plan?.blockers.length ? "danger" : "success"}>{stale ? "Expired" : plan?.blockers.length ? "Blocked" : "Ready to apply"}</StatusBadge>} />
    <div className="plan-metadata"><div><span>AWS account</span><strong className="mono">{plan?.accountId ?? "Unknown"}</strong><small>Account ID reported by provider</small></div><div><span>Region</span><strong className="mono">{plan?.region ?? env.region}</strong><small>AWS</small></div><div><span>Observed</span><strong>{plan ? relativeTime(plan.createdAt) : "Unknown"}</strong><small>{plan ? new Date(plan.createdAt).toLocaleString() : "Not reported"}</small></div><div><span>Plan expires</span><strong>{plan ? relativeTime(plan.expiresAt) : "Unknown"}</strong><small>{plan ? new Date(plan.expiresAt).toLocaleString() : "Not reported"}</small></div></div>
    <div className="plan-summary"><span className="plan-count plan-count--add">{changes.filter((change) => change.action === "create").length} create</span><span className="plan-count plan-count--change">{changes.filter((change) => change.action === "update").length} update</span><span>{changes.filter((change) => change.action === "replace").length} replace</span><span>{changes.filter((change) => change.action === "delete").length} delete</span><span>{changes.filter((change) => change.action === "same").length} no-op</span></div>
    {["Infrastructure", "Nodes", "Workloads"].filter((group) => changes.some((change) => change.group === group)).map((group) => <section className="plan-group" key={group}><header><h2>{group}</h2><span>{changes.filter((change) => change.group === group).length} changes</span></header>{changes.filter((change) => change.group === group).map((change, index) => <div className="diff-row" key={`${change.title}-${index}`}><span className={`diff-symbol diff-symbol--${change.tone}`}>{change.symbol}</span><span><strong>{change.title}</strong><small>{change.detail}</small></span></div>)}</section>)}
    {!changes.length ? <EmptyState icon={FileDiff} title="No changes" detail="Provider observation and desired revision already agree." /> : null}
    {plan?.blockers.map((blocker, index) => <IssueBanner key={`${blocker}-${index}`} tone="danger" title="Plan blocker">{blocker}</IssueBanner>)}
    {stale ? <IssueBanner tone="danger" title="Plan expired">Generate a fresh plan. Apply is disabled because provider state may have changed.</IssueBanner> : changes.some((change) => change.action === "delete" || change.action === "replace" || (change.action !== "same" && plan?.changes.find((item) => item.resourceKey === change.title)?.destructive)) ? <IssueBanner tone="warning" title="Destructive changes require close review">This plan includes deletion or replacement. Review every affected resource before applying.</IssueBanner> : <IssueBanner tone="info" title="No destructive changes">The persisted plan marks no change as destructive.</IssueBanner>}
    <label className="check-row"><input type="checkbox" checked={ack} onChange={(event) => setAck(event.target.checked)} /><span><strong>I reviewed the account, region, and exposed ports.</strong><small>Apply will stop if provider state changes before execution.</small></span></label>
    {applyError ? <IssueBanner tone="danger" title="Apply could not be started">{applyError}</IssueBanner> : null}
    <footer className="sticky-actions"><span><ShieldCheck /> Bound to revision {plan?.revision ?? "unknown"} · digest <code>{plan ? `${plan.revisionDigest.slice(0, 8)}…` : "unknown"}</code></span><div><Button variant="secondary" onClick={() => navigate(`/environments/${environmentId}`)}>Keep as draft</Button><Button disabled={!ack || applying || stale || Boolean(plan?.blockers.length) || !plan} onClick={applyPlan}>{applying ? "Starting…" : "Apply plan"} <ArrowRight /></Button></div></footer>
  </div>;
}

export function OperationPage() {
  const { environmentId = "" } = useParams(); const fallbackEnv = environmentById(environmentId); const [params] = useSearchParams(); const location = useLocation();
  const routeState = location.state as { environment?: { name: string }; operation?: Operation } | null;
  const operationId = params.get("operationId") ?? routeState?.operation?.id;
  const [events, setEvents] = useState<OperationEvent[]>([]); const [reconnecting, setReconnecting] = useState(false);
  const query = useQuery({ queryKey: ["operation", operationId], queryFn: () => getOperation(operationId!), enabled: Boolean(operationId), initialData: routeState?.operation, refetchInterval: (state) => state.state.data && ["queued", "running", "waiting", "cancelling"].includes(state.state.data.state) ? 1500 : false });
  const environmentQuery = useQuery({ queryKey: ["environment", environmentId], queryFn: () => getEnvironment(environmentId), enabled: Boolean(environmentId) && !routeState?.environment });
  useEffect(() => operationId ? subscribeToOperation(operationId, (event) => { setEvents((current) => current.some(({ id }) => id === event.id) ? current : [...current, event].slice(-80)); setReconnecting(false); }, () => setReconnecting(true)) : undefined, [operationId]);
  const operation = query.data;
  const demoFailure = demoMode && params.get("state") === "failed" && !operation;
  const kind = operation?.kind ?? "apply";
  const state = operation?.state ?? (demoFailure ? "failed" : "queued");
  const attention = ["failed", "blocked", "needs_reconciliation"].includes(state);
  const kindLabel = { plan: "Plan", apply: "Apply", reconcile: "Reconciliation", destroy: "Destroy", abandon: "Abandon" }[kind];
  const activeTitle = { plan: "Planning environment", apply: "Applying environment", reconcile: "Reconciling environment", destroy: "Destroying environment", abandon: "Abandoning environment" }[kind];
  const title = state === "succeeded" ? `${kindLabel} completed` : state === "cancelled" ? `${kindLabel} cancelled` : attention ? `${kindLabel} needs attention` : activeTitle;
  const description = state === "succeeded"
    ? kind === "plan" ? "The provider observation and immutable plan result were persisted." : kind === "destroy" ? "The destroy sequence and residual-resource audit completed as reported by the control plane." : "Every persisted step completed as reported by the control plane."
    : state === "needs_reconciliation" ? "The external outcome is unknown. Observe actual state before starting another mutation."
      : state === "failed" ? "The operation stopped. External state may be partial and must be inspected before retrying."
        : state === "blocked" ? "The operation cannot continue until its reported blocker is resolved."
          : state === "cancelled" ? "Cancellation completed at a persisted step boundary. Review actual state before another mutation."
            : "Progress is persisted. You can navigate away and return to this operation."
  const actualSteps = operation?.steps.length ? operation.steps.map((step) => ({
    name: step.title,
    state: step.state === "succeeded" || step.state === "skipped" ? "complete" as const : step.state === "running" || step.state === "waiting" ? "active" as const : step.state === "failed" ? "failed" as const : "pending" as const,
    detail: step.errorMessage ?? (step.state === "succeeded" ? "Completed" : step.state === "running" ? "In progress" : step.state === "waiting" ? "Waiting" : step.state === "skipped" ? "Skipped" : step.state === "cancelled" ? "Cancelled" : "Not started"),
    raw: step
  })) : demoMode ? operationSteps.map((step) => ({ ...step, raw: null })) : [];
  const steps = demoFailure ? actualSteps.map((step, index) => index === 6 ? { ...step, state: "failed" as const, detail: "Simulated health probe timeout" } : index < 6 ? { ...step, state: "complete" as const } : step) : actualSteps;
  const failedStep = operation?.steps.find((step) => step.state === "failed");
  const latestError = [...events].reverse().find((event) => event.level === "error");
  const diagnostic = failedStep?.errorMessage ?? latestError?.message ?? (demoFailure ? "A simulated workload health probe timed out." : "No step diagnostic has been reported.");
  const completed = steps.filter((step) => step.state === "complete").length;
  const currentIndex = Math.max(0, steps.findIndex((step) => step.state === "active" || step.state === "failed"));
  const currentStep = steps[currentIndex];
  const progress = state === "succeeded" ? 100 : steps.length ? Math.round((completed / steps.length) * 100) : 0;
  const startedAt = operation?.startedAt ?? operation?.createdAt;
  const elapsedSeconds = startedAt ? Math.max(0, Math.round(((operation?.finishedAt ? new Date(operation.finishedAt).getTime() : Date.now()) - new Date(startedAt).getTime()) / 1000)) : null;
  const elapsed = elapsedSeconds === null ? "Not started" : elapsedSeconds < 60 ? `${elapsedSeconds} seconds` : elapsedSeconds < 3600 ? `${Math.floor(elapsedSeconds / 60)}m ${elapsedSeconds % 60}s` : `${Math.floor(elapsedSeconds / 3600)}h ${Math.floor((elapsedSeconds % 3600) / 60)}m`;
  const safety = kind === "plan" ? "Read-only provider observation" : state === "needs_reconciliation" ? "Unknown · observe before retry" : state === "failed" || state === "blocked" ? "Partial or unknown · inspect state" : state === "cancelled" ? "Stopped at a persisted boundary" : state === "succeeded" ? kind === "destroy" ? "Destroy and residue audit reported complete" : "All persisted steps reported complete" : kind === "destroy" ? "Destructive work may be in progress" : "External state may be changing";
  const envName = routeState?.environment?.name ?? environmentQuery.data?.name ?? (demoMode ? fallbackEnv.name : "Environment");
  const recoveryHref = kind === "destroy" || kind === "abandon" ? `/environments/${environmentId}/settings` : `/environments/${environmentId}/plan`;
  const recoveryLabel = kind === "destroy" || kind === "abandon" ? "Review environment" : "Refresh and review a plan";
  if (!operationId && !demoFailure) return <div className="page page--wide"><IssueBanner tone="danger" title="Operation ID is missing">Open an operation from its returned operation resource or activity history.</IssueBanner></div>;
  if (query.isLoading && !operation) return <div className="page page--wide"><Skeleton rows={9} /></div>;
  if (query.error) return <div className="page page--wide"><IssueBanner tone="danger" title="Operation could not be loaded">{query.error instanceof ApiError ? query.error.detail ?? query.error.message : "The operation is unavailable."}</IssueBanner></div>;
  return <div className="page page--wide"><Link to={`/environments/${environmentId}`} className="back-link"><ArrowLeft /> {envName}</Link><PageHeader eyebrow={`Operation ${operationId?.slice(0, 8) ?? "simulated"}`} title={title} description={description} action={<StatusBadge tone={state === "succeeded" ? "success" : state === "failed" || state === "needs_reconciliation" ? "danger" : state === "blocked" ? "warning" : state === "cancelled" ? "neutral" : "info"}>{state.replaceAll("_", " ")}</StatusBadge>} />
    {attention ? <IssueBanner tone={state === "blocked" ? "warning" : "danger"} title={failedStep ? `${failedStep.title} ${state === "blocked" ? "is blocked" : "failed"}` : `${kindLabel} ${state.replaceAll("_", " ")}`} actions={<ButtonLink to={recoveryHref} icon={RefreshCw}>{recoveryLabel}</ButtonLink>}>{diagnostic}</IssueBanner> : null}
    <section className="operation-progress"><div><span>{steps.length ? `Step ${Math.min(currentIndex + 1, steps.length)} of ${steps.length}` : "No steps reported"}</span><strong>{currentStep?.name ?? (state === "queued" ? "Waiting to start" : title)}</strong></div><span>{progress}%</span><ProgressBar value={progress} /><small>Elapsed {elapsed} · {events.at(-1) ? `last event ${relativeTime(events.at(-1)!.createdAt)}` : "no stream event received"}</small></section>
    <div className="operation-layout"><section className="timeline"><h2>Operation timeline</h2>{steps.length ? steps.map((step, index) => <div className={`timeline-step timeline-step--${step.state}`} key={`${step.name}-${index}`}><span>{step.state === "complete" ? <Check /> : step.state === "active" ? <RefreshCw className="spin" /> : step.state === "failed" ? <XCircle /> : index + 1}</span><div><strong>{step.name}</strong><small>{step.detail}</small></div>{step.state === "active" ? <StatusBadge tone="info">In progress</StatusBadge> : step.state === "failed" ? <StatusBadge tone="danger">Failed</StatusBadge> : null}</div>) : <EmptyState icon={RefreshCw} title="No steps reported" detail="The operation exists, but the control plane has not returned its fixed step sequence yet." />}</section><aside className="operation-aside"><section className="panel"><h2>Current state</h2><DefinitionList items={[["Operation", kindLabel], ["Safety", safety], ["Revision", operation ? String(operation.revision) : "Simulated"], ["Completed", `${completed} of ${steps.length} steps`], ["Correlation ID", <code>{operationId ?? "simulated"}</code>]]} /></section>{attention ? <section className="panel"><h2>Recommended action</h2><p>{state === "needs_reconciliation" ? "Refresh actual state in a new reviewed plan before any retry." : kind === "destroy" ? "Review the failed step and residual details. Do not assume any managed resource was removed." : kind === "plan" ? "Resolve the reported blocker, then generate a fresh provider observation and plan." : "Refresh actual state and review the resulting plan before another mutation."}</p><ButtonLink to={recoveryHref} icon={RefreshCw}>{recoveryLabel}</ButtonLink></section> : null}<section className="panel"><h2>Live events</h2><div className="live-event"><span className={reconnecting ? "state-dot state-dot--unknown" : "live-dot"} /><p>{reconnecting ? "Reconnecting to the durable event stream…" : events.at(-1)?.message ?? "Waiting for the next persisted event."}</p></div><details><summary>Show technical details</summary><pre className="log-viewer">{events.length ? events.map((event) => `${new Date(event.createdAt).toLocaleTimeString()} [${event.level}] ${event.message}`).join("\n") : "No operation events received yet."}{operation?.result ? `\n\nResult\n${JSON.stringify(operation.result, null, 2)}` : ""}</pre></details></section></aside></div>
  </div>;
}

export function DestroyPage() {
  const { environmentId = "" } = useParams(); const navigate = useNavigate(); const [name, setName] = useState(""); const [ack, setAck] = useState(false); const [starting, setStarting] = useState(false); const [startError, setStartError] = useState<string | null>(null);
  const environmentQuery = useQuery({ queryKey: ["environment", environmentId], queryFn: () => getEnvironment(environmentId) });
  if (environmentQuery.isLoading) return <div className="page page--narrow"><Skeleton rows={8} /></div>;
  if (environmentQuery.error || !environmentQuery.data) return <div className="page page--narrow"><IssueBanner tone="danger" title="Destroy plan could not be prepared">{environmentQuery.error instanceof Error ? environmentQuery.error.message : "The environment is unavailable."}</IssueBanner></div>;
  const env = environmentQuery.data; const managedNodes = env.spec.nodes.filter((node) => node.source.kind === "aws"); const adoptedNodes = env.spec.nodes.filter((node) => node.source.kind === "adopted"); const ready = name === env.name && ack;
  const destroy = async () => { setStarting(true); setStartError(null); try { const operation = await startDestroy(env.id, name, ack); navigate(`/environments/${env.id}/operation?operationId=${operation.id}`, { state: { operation, environment: env } }); } catch (error) { setStartError(error instanceof ApiError ? error.detail ?? error.message : "Destroy could not be started."); } finally { setStarting(false); } };
  return <div className="page page--narrow"><Link to={`/environments/${env.id}/settings`} className="back-link"><ArrowLeft /> Environment settings</Link><PageHeader eyebrow="Destructive operation" title={`Destroy ${env.name}`} description="Review what will be removed, detached, and retained. This action never assumes cleanup succeeded." />
    {adoptedNodes.length ? <IssueBanner tone="warning" title={`${adoptedNodes.length} adopted ${adoptedNodes.length === 1 ? "host" : "hosts"} will be detached`}>Infractory will remove its workloads and network membership when reachable. It will never delete or reboot an adopted host.</IssueBanner> : null}
    <section className="destroy-plan"><h2>Destroy intent</h2><div className="destroy-group"><header><span className="danger-icon"><Trash2 /></span><span><strong>Managed infrastructure removed</strong><small>{managedNodes.length} managed {managedNodes.length === 1 ? "node" : "nodes"} plus owned network resources</small></span></header><ul><li>{managedNodes.map((node) => node.name).join(", ") || "No managed nodes"}</li><li>{env.spec.deployments.length} desired workload {env.spec.deployments.length === 1 ? "deployment" : "deployments"}</li><li>Exact provider resources are refreshed and audited during the operation.</li></ul></div><div className="destroy-group"><header><span className="warning-icon"><Laptop /></span><span><strong>Adopted resources detached</strong><small>{adoptedNodes.length} {adoptedNodes.length === 1 ? "host" : "hosts"}</small></span></header><ul><li>{adoptedNodes.map((node) => node.name).join(", ") || "No adopted hosts"}</li><li>The hosts, operating systems, and unrelated data remain untouched.</li></ul></div><div className="destroy-group"><header><span className="neutral-icon"><HardDrive /></span><span><strong>Records retained</strong><small>Audit history</small></span></header><ul><li>Environment revisions, operation timeline, and residue reports</li><li>Completion is reported only after provider refresh and residue audit.</li></ul></div></section>
    <section className="confirm-block"><h2>Confirm destruction</h2><label className="field"><span>Type <strong>{env.name}</strong> to continue</span><input value={name} onChange={(event) => setName(event.target.value)} autoComplete="off" /></label><label className="check-row"><input type="checkbox" checked={ack} onChange={(event) => setAck(event.target.checked)} /><span><strong>I understand offline adopted hosts may require manual cleanup.</strong><small>Any residual resources will be reported explicitly.</small></span></label></section>
    {startError ? <IssueBanner tone="danger" title="Destroy could not be started">{startError}</IssueBanner> : null}
    <footer className="form-footer"><ButtonLink to={`/environments/${env.id}/settings`} variant="secondary">Cancel</ButtonLink><Button variant="danger" icon={Trash2} disabled={!ready || starting} onClick={destroy}>{starting ? "Starting…" : "Start destroy operation"}</Button></footer>
  </div>;
}

export function AdoptHostPage() {
  const { environmentId = "" } = useParams(); const env = environmentById(environmentId); const [copied, setCopied] = useState(false); const [stage, setStage] = useState<"instructions" | "waiting" | "ready">("instructions"); const [enrollment, setEnrollment] = useState<{ token: string; expiresAt: string } | null>(null); const [enrollError, setEnrollError] = useState<string | null>(null); const [creating, setCreating] = useState(false);
  const nodeQuery = useQuery({ queryKey: ["nodes", environmentId], queryFn: () => listNodes(environmentId), enabled: !demoMode, refetchInterval: stage === "waiting" ? 2000 : false });
  const adopted = demoMode ? { id: "demo-adopted-node", name: "operator-core" } : nodeQuery.data?.find((node) => node.origin === "adopted" && node.lifecycle !== "detached");
  const observedNode = nodeQuery.data?.find((node) => node.id === adopted?.id);
  const origin = window.location.origin; const command = enrollment ? `set -eu
case "$(uname -m)" in
  x86_64) agent_arch=amd64 ;;
  aarch64|arm64) agent_arch=arm64 ;;
  *) echo "Unsupported architecture: $(uname -m)" >&2; exit 1 ;;
esac
base_url='${origin}'
work_dir="$(mktemp -d)"
trap 'rm -rf "$work_dir"' EXIT
curl --proto '=https' --tlsv1.2 -fsSL "$base_url/artifacts/SHA256SUMS" -o "$work_dir/SHA256SUMS"
curl --proto '=https' --tlsv1.2 -fsSL "$base_url/artifacts/infractory-agent-linux-$agent_arch" -o "$work_dir/infractory-agent-linux-$agent_arch"
grep "  infractory-agent-linux-$agent_arch$" "$work_dir/SHA256SUMS" > "$work_dir/CHECKSUM"
(cd "$work_dir" && sha256sum -c CHECKSUM)
sudo install -d -o root -g root -m 0755 /var/lib/infractory/bin /etc/infractory-agent
sudo install -o root -g root -m 0755 "$work_dir/infractory-agent-linux-$agent_arch" /var/lib/infractory/bin/infractory-agent
printf 'Enrollment token: ' >&2
stty -echo
IFS= read -r enrollment_token
stty echo
printf '\n' >&2
sudo install -o root -g root -m 0600 /dev/null /var/lib/infractory/enrollment-token
printf '%s\n' "$enrollment_token" | sudo tee /var/lib/infractory/enrollment-token >/dev/null
unset enrollment_token
sudo chown root:root /var/lib/infractory/enrollment-token
sudo chmod 0600 /var/lib/infractory/enrollment-token
sudo tee /etc/infractory-agent/config.json >/dev/null <<'JSON'
{"controlPlaneUrl":"${origin}","stateDir":"/var/lib/infractory","enrollmentTokenFile":"/var/lib/infractory/enrollment-token"}
JSON
sudo chmod 0600 /etc/infractory-agent/config.json
sudo tee /etc/systemd/system/infractory-agent.service >/dev/null <<'UNIT'
[Unit]
Description=Infractory v2 node agent
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
ExecStart=/var/lib/infractory/bin/infractory-agent run --config /etc/infractory-agent/config.json
Restart=always
RestartSec=5s
User=root
Group=root
UMask=0077
NoNewPrivileges=true
PrivateTmp=true
ProtectHome=true
StateDirectory=infractory

[Install]
WantedBy=multi-user.target
UNIT
sudo systemctl daemon-reload
sudo systemctl enable --now infractory-agent` : "Generate a one-use token to receive an enrollment command.";
  const copy = async () => { await navigator.clipboard?.writeText(command); setCopied(true); setTimeout(() => setCopied(false), 1800); };
  const prepareEnrollment = async () => { if (!adopted) return; setCreating(true); setEnrollError(null); try { setEnrollment(await createEnrollment(environmentId, adopted.id)); } catch (error) { setEnrollError(error instanceof ApiError ? error.detail ?? error.message : "Enrollment could not be prepared."); } finally { setCreating(false); } };
  useEffect(() => { if (!demoMode && stage === "waiting" && observedNode?.lifecycle === "active" && observedNode.health === "online") setStage("ready"); }, [observedNode?.health, observedNode?.lifecycle, stage]);
  if (!demoMode && nodeQuery.isLoading) return <div className="page page--narrow"><Skeleton rows={8} /></div>;
  if (!demoMode && nodeQuery.error) return <div className="page page--narrow"><IssueBanner tone="danger" title="Nodes could not be loaded">{nodeQuery.error instanceof Error ? nodeQuery.error.message : "The environment is unavailable."}</IssueBanner></div>;
  if (!adopted) return <div className="page page--narrow"><Link to={`/environments/${environmentId}/nodes`} className="back-link"><ArrowLeft /> Nodes</Link><EmptyState icon={Laptop} title="No adopted host is ready to enroll" detail="Add an adopted node to the environment specification, then return here." /></div>;
  return <div className="page page--narrow"><Link to={`/environments/${environmentId}/nodes`} className="back-link"><ArrowLeft /> Nodes</Link><PageHeader eyebrow="Adopted node" title="Enroll an existing host" description="The agent connects outbound over HTTPS. No inbound management port or SSH access is required." />
    <ol className="stepper stepper--three"><li className="complete"><span><Check /></span><small>Prerequisites</small></li><li className={stage === "waiting" ? "active" : stage === "ready" ? "complete" : "active"}><span>{stage === "ready" ? <Check /> : 2}</span><small>Enroll</small></li><li className={stage === "ready" ? "active" : ""}><span>3</span><small>Confirm</small></li></ol>
    {stage === "instructions" ? <section className="form-surface"><div className="form-section"><h2>Run on the host</h2><p>Supported: Ubuntu 22.04/24.04 and Debian 12 on amd64 or arm64.</p><div className="prerequisite-grid"><span><CheckCircle2 /> Root or sudo access</span><span><CheckCircle2 /> Outbound HTTPS</span><span><CheckCircle2 /> TUN device</span><span><CheckCircle2 /> systemd</span></div><label className="field"><span>Node name</span><input value={adopted.name} readOnly /></label>{!enrollment ? <Button icon={KeyRound} onClick={prepareEnrollment} disabled={creating}>{creating ? "Generating…" : "Generate one-use token"}</Button> : <><IssueBanner tone="info" title="Checksum verification is included">The command selects the host architecture, verifies the downloaded agent against this control plane's published SHA-256 manifest, and prompts for the token without placing it in process arguments.</IssueBanner><div className="command-box"><code>{command}</code><Button variant="secondary" icon={Copy} onClick={copy}>{copied ? "Copied" : "Copy"}</Button></div><div className="token-row"><KeyRound /><span><strong>One-use token</strong><small>Expires {relativeTime(enrollment.expiresAt)} · shown only now</small></span><code>{enrollment.token}</code></div></>}{enrollError ? <IssueBanner tone="danger" title="Enrollment could not be prepared">{enrollError}</IssueBanner> : null}</div><footer className="form-footer"><ButtonLink to={`/environments/${environmentId}/nodes`} variant="secondary">Cancel</ButtonLink><Button onClick={() => setStage("waiting")} disabled={!enrollment}>I ran the command <ArrowRight /></Button></footer></section> : null}
    {stage === "waiting" ? <section className="waiting-card" aria-live="polite"><span className="waiting-orb"><RefreshCw className="spin" /></span><h2>Waiting for {adopted.name}</h2><p>{enrollment ? `Token expires ${relativeTime(enrollment.expiresAt)}.` : "Waiting for a secure agent connection."} Leave this page open or return later.</p><div className="diagnostic-list"><span className="complete"><Check /> Enrollment token created</span><span className="active"><RefreshCw className="spin" /> Waiting for secure connection</span><span><Circle /> Inspect host capabilities</span></div>{demoMode ? <Button onClick={() => setStage("ready")}>Simulate connection</Button> : <Button variant="secondary" onClick={() => nodeQuery.refetch()} icon={RefreshCw}>Check now</Button>}</section> : null}
    {stage === "ready" ? <section className="form-surface"><div className="form-section"><div className="success-heading"><CheckCircle2 /><span><h2>Host enrollment confirmed</h2><p>{demoMode ? "Capabilities were observed directly from the simulated agent." : "The agent enrolled successfully and reported the node online."}</p></span></div><DefinitionList items={demoMode ? [["Operating system", "Ubuntu 24.04.1 LTS"], ["Architecture", "amd64"], ["Docker", "27.1.1 · Compose 2.29.1"], ["TUN device", "Available"], ["Clock drift", "142 ms"], ["Network", "UDP/4242 reachable"]] : [["Node", adopted.name], ["Lifecycle", observedNode?.lifecycle ?? "unknown"], ["Health", observedNode?.health ?? "unknown"], ["Last observed", observedNode?.lastSeenAt ? new Date(observedNode.lastSeenAt).toLocaleString() : "Not reported"]]} /><IssueBanner tone="info" title="Placement comes from the environment specification">Node roles are changed through a new environment revision, where their effects can be reviewed before apply.</IssueBanner></div><footer className="form-footer"><ButtonLink to={`/environments/${environmentId}/nodes`} variant="secondary">Return to nodes</ButtonLink><Button onClick={async () => { const operation = await startPlan(environmentId); location.assign(`/environments/${environmentId}/plan?operationId=${operation.id}`); }}>Refresh environment plan</Button></footer></section> : null}
  </div>;
}

export function WorkloadsPage() { const query = useQuery({ queryKey: ["workloads"], queryFn: listWorkloads, enabled: !demoMode }); const items = demoMode ? workloadCatalog : query.data?.map((item) => ({ id: item.id, name: item.name, description: item.description, latest: "—", versions: 0, updated: relativeTime(item.createdAt), state: "Published" })) ?? []; return <div className="page"><PageHeader title="Workloads" description="Trusted, versioned packages that can be deployed consistently across environments." action={<ButtonLink to="/workloads/import" icon={Upload}>Import workload</ButtonLink>} />{query.error ? <IssueBanner tone="danger" title="Workloads could not be loaded">{query.error instanceof Error ? query.error.message : "The workload catalog is unavailable."}</IssueBanner> : query.isLoading && !demoMode ? <Skeleton rows={6} /> : items.length === 0 ? <EmptyState title="No workloads published" detail="Import a restricted Compose package to create the first immutable workload version." action={<ButtonLink to="/workloads/import" icon={Upload}>Import workload</ButtonLink>} /> : <div className="catalog-grid">{items.map((item) => <Link to={`/workloads/${item.id}`} className="catalog-card" key={item.id}><span className="catalog-card__icon"><Package /></span><div><div className="catalog-card__title"><h2>{item.name}</h2><StatusBadge tone="success">{item.state}</StatusBadge></div><p>{item.description}</p><footer><span>Latest <strong>{item.latest}</strong></span><span>{item.versions} versions</span><span>Created {item.updated}</span></footer></div><ChevronRight /></Link>)}</div>}</div>; }

export function WorkloadImportPage() {
  type InputDraft = { id: string; name: string; type: "string" | "number" | "boolean"; required: boolean };
  type SecretDraft = { id: string; input: string; target: string };
  type EndpointDraft = { id: string; name: string; protocol: "tcp" | "udp" | "http"; port: number; scope: "public" | "overlay" };
  type ProbeDraft = { id: string; kind: "container" | "http" | "tcp"; target: string; timeoutSeconds: number };
  const id = () => crypto.randomUUID();
  const navigate = useNavigate(); const queryClient = useQueryClient(); const [step, setStep] = useState(1); const [composeYaml, setComposeYaml] = useState(""); const [name, setName] = useState(""); const [description, setDescription] = useState(""); const [version, setVersion] = useState("1.0.0"); const [roles, setRoles] = useState("redirector"); const [inputs, setInputs] = useState<InputDraft[]>([]); const [secrets, setSecrets] = useState<SecretDraft[]>([]); const [endpoints, setEndpoints] = useState<EndpointDraft[]>([]); const [probes, setProbes] = useState<ProbeDraft[]>([]); const [publishing, setPublishing] = useState(false); const [publishError, setPublishError] = useState<string | null>(null); const [draftWorkloadId, setDraftWorkloadId] = useState<string | null>(null); const [published, setPublished] = useState<{ workloadId: string; digest: string } | null>(null);
  const steps = ["Package", "Compose", "Inputs", "Runtime", "Review"];
  const inputNames = new Set(inputs.map((input) => input.name));
  const duplicateInputs = inputNames.size !== inputs.length;
  const invalidSecrets = secrets.some((secret) => {
    const segments = secret.target.split("/");
    return !inputNames.has(secret.input) || !secret.target || secret.target.startsWith("/") || segments.includes("..");
  });
  const manifest: WorkloadManifest = {
    schemaVersion: 1,
    inputsSchema: { type: "object", properties: Object.fromEntries(inputs.map((input) => [input.name, { type: input.type }])), required: inputs.filter((input) => input.required).map((input) => input.name), additionalProperties: false },
    secretFiles: secrets.map(({ input, target }) => ({ input, target })),
    endpoints: endpoints.map(({ name, protocol, port, scope }) => ({ name, protocol, port, scope })),
    placement: { requiredRoles: [...new Set(roles.split(",").map((role) => role.trim().toLowerCase()).filter(Boolean))] },
    probes: probes.map(({ kind, target, timeoutSeconds }) => ({ kind, target, timeoutSeconds }))
  };
  const stepValid = step === 1 ? name.trim().length > 1 && /^\d+\.\d+\.\d+(?:[-+][0-9A-Za-z.-]+)?$/.test(version) : step === 2 ? Boolean(composeYaml) : step === 3 ? inputs.every((input) => /^[a-z][a-z0-9_]*$/.test(input.name)) && !duplicateInputs && !invalidSecrets : step === 4 ? endpoints.every((endpoint) => endpoint.name.trim() && endpoint.port > 0 && endpoint.port <= 65535) && probes.every((probe) => probe.target.trim() && probe.timeoutSeconds > 0 && probe.timeoutSeconds <= 60) : true;
  const publish = async () => { setPublishing(true); setPublishError(null); try { const workloadId = draftWorkloadId ?? (await createWorkload(name, description)).id; setDraftWorkloadId(workloadId); const release = await createWorkloadVersion(workloadId, version, composeYaml, manifest); setPublished({ workloadId, digest: release.digest }); await queryClient.invalidateQueries({ queryKey: ["workloads"] }); } catch (error) { setPublishError(error instanceof ApiError ? error.detail ?? error.message : "The workload could not be published."); } finally { setPublishing(false); } };
  const next = () => { if (stepValid) { setPublishError(null); setStep(Math.min(5, step + 1)); } else setPublishError("Complete the required fields on this step before continuing."); };
  return <div className="page page--narrow"><Link to="/workloads" className="back-link"><ArrowLeft /> Workloads</Link><PageHeader eyebrow={`Step ${step} of 5`} title="Import workload" description="Define an immutable, restricted Compose package operators can deploy with confidence." />
    {!published ? <><ol className="stepper" aria-label="Workload import progress">{steps.map((label, index) => <li key={label} className={index + 1 === step ? "active" : index + 1 < step ? "complete" : ""}><span>{index + 1 < step ? <Check /> : index + 1}</span><small>{label}</small></li>)}</ol><section className="form-surface"><div className="form-section">
      {step === 1 ? <><h2>Package identity</h2><p>A package groups immutable versions under a stable, operator-friendly name.</p><div className="field-row"><label className="field"><span>Package name</span><input autoFocus value={name} onChange={(event) => setName(event.target.value)} placeholder="HTTP redirector" /></label><label className="field"><span>Semantic version</span><input value={version} onChange={(event) => setVersion(event.target.value)} className="mono" placeholder="1.0.0" /></label></div><label className="field"><span>Description</span><textarea rows={4} value={description} onChange={(event) => setDescription(event.target.value)} placeholder="What this workload provides and when to use it." /></label></> : null}
      {step === 2 ? <><h2>Compose definition</h2><p>Upload the exact Compose YAML that will be normalized and validated by the control plane.</p><label className={`drop-zone ${composeYaml ? "drop-zone--complete" : ""}`}><input type="file" accept=".yaml,.yml" onChange={async (event) => { const file = event.target.files?.[0]; if (!file) return; if (file.size > 1_048_576) { setPublishError("Compose YAML must be smaller than 1 MB."); return; } setComposeYaml(await file.text()); }} />{composeYaml ? <><FileCheck2 /><strong>Compose YAML loaded</strong><small>{composeYaml.split("\n").length} lines · server validation occurs at publish</small></> : <><Upload /><strong>Choose Compose YAML</strong><small>or drop the file here · maximum 1 MB</small></>}</label><label className="field"><span>Compose YAML</span><textarea className="mono code-editor" rows={12} value={composeYaml} onChange={(event) => setComposeYaml(event.target.value)} placeholder={'services:\n  app:\n    image: example/app@sha256:…'} spellCheck={false} /></label><IssueBanner tone="info" title="Restricted by design">Privileged containers, host networking, Docker socket mounts, undeclared host paths, and undeclared published ports are rejected.</IssueBanner></> : null}
      {step === 3 ? <><h2>Inputs and secret files</h2><p>Inputs become typed deployment fields. Secret targets are relative to this deployment's immutable release.</p><div className="builder-list">{inputs.map((input) => <div className="builder-row builder-row--input" key={input.id}><label className="field"><span>Input name</span><input value={input.name} onChange={(event) => setInputs((current) => current.map((item) => item.id === input.id ? { ...item, name: event.target.value } : item))} placeholder="upstream_url" /></label><label className="field"><span>Type</span><select value={input.type} onChange={(event) => setInputs((current) => current.map((item) => item.id === input.id ? { ...item, type: event.target.value as InputDraft["type"] } : item))}><option>string</option><option>number</option><option>boolean</option></select></label><label className="compact-check"><input type="checkbox" checked={input.required} onChange={(event) => setInputs((current) => current.map((item) => item.id === input.id ? { ...item, required: event.target.checked } : item))} /> Required</label><button className="icon-button" onClick={() => setInputs((current) => current.filter((item) => item.id !== input.id))} aria-label={`Remove ${input.name || "input"}`}><Trash2 /></button></div>)}<Button variant="secondary" icon={Plus} onClick={() => setInputs((current) => [...current, { id: id(), name: "", type: "string", required: true }])}>Add input</Button>{duplicateInputs ? <p className="field-error">Input names must be unique.</p> : null}</div><div className="subsection"><h3>Secret file targets</h3>{secrets.map((secret) => <div className="builder-row" key={secret.id}><label className="field"><span>Secret input</span><select value={secret.input} onChange={(event) => setSecrets((current) => current.map((item) => item.id === secret.id ? { ...item, input: event.target.value } : item))}><option value="">Select input</option>{inputs.map((input) => <option key={input.id} value={input.name}>{input.name || "Unnamed input"}</option>)}</select></label><label className="field"><span>Release-relative target</span><input className="mono" value={secret.target} onChange={(event) => setSecrets((current) => current.map((item) => item.id === secret.id ? { ...item, target: event.target.value } : item))} placeholder="secrets/token" /></label><button className="icon-button" onClick={() => setSecrets((current) => current.filter((item) => item.id !== secret.id))} aria-label="Remove secret target"><Trash2 /></button></div>)}<Button variant="secondary" icon={Plus} disabled={!inputs.length} onClick={() => setSecrets((current) => [...current, { id: id(), input: inputs[0]?.name ?? "", target: "secrets/credential" }])}>Add secret target</Button>{invalidSecrets ? <p className="field-error">Each secret must reference an input and use a relative path without `..` segments.</p> : null}</div></> : null}
      {step === 4 ? <><h2>Placement, endpoints, and health</h2><p>Make runtime requirements explicit so plans can block incompatible deployments.</p><label className="field"><span>Required node roles <em>Comma separated</em></span><input value={roles} onChange={(event) => setRoles(event.target.value)} placeholder="redirector, public-edge" /></label><div className="subsection"><h3>Declared endpoints</h3>{endpoints.map((endpoint) => <div className="builder-row builder-row--endpoint" key={endpoint.id}><label className="field"><span>Name</span><input value={endpoint.name} onChange={(event) => setEndpoints((current) => current.map((item) => item.id === endpoint.id ? { ...item, name: event.target.value } : item))} placeholder="HTTPS" /></label><label className="field"><span>Protocol</span><select value={endpoint.protocol} onChange={(event) => setEndpoints((current) => current.map((item) => item.id === endpoint.id ? { ...item, protocol: event.target.value as EndpointDraft["protocol"] } : item))}><option>tcp</option><option>udp</option><option>http</option></select></label><label className="field"><span>Port</span><input type="number" min="1" max="65535" value={endpoint.port} onChange={(event) => setEndpoints((current) => current.map((item) => item.id === endpoint.id ? { ...item, port: Number(event.target.value) } : item))} /></label><label className="field"><span>Scope</span><select value={endpoint.scope} onChange={(event) => setEndpoints((current) => current.map((item) => item.id === endpoint.id ? { ...item, scope: event.target.value as EndpointDraft["scope"] } : item))}><option>overlay</option><option>public</option></select></label><button className="icon-button" onClick={() => setEndpoints((current) => current.filter((item) => item.id !== endpoint.id))} aria-label={`Remove ${endpoint.name || "endpoint"}`}><Trash2 /></button></div>)}<Button variant="secondary" icon={Plus} onClick={() => setEndpoints((current) => [...current, { id: id(), name: "", protocol: "tcp", port: 443, scope: "overlay" }])}>Add endpoint</Button></div><div className="subsection"><h3>Health probes</h3>{probes.map((probe) => <div className="builder-row builder-row--probe" key={probe.id}><label className="field"><span>Kind</span><select value={probe.kind} onChange={(event) => setProbes((current) => current.map((item) => item.id === probe.id ? { ...item, kind: event.target.value as ProbeDraft["kind"] } : item))}><option>container</option><option>http</option><option>tcp</option></select></label><label className="field"><span>Target</span><input value={probe.target} onChange={(event) => setProbes((current) => current.map((item) => item.id === probe.id ? { ...item, target: event.target.value } : item))} placeholder="http://app:8080/health" /></label><label className="field"><span>Timeout</span><input type="number" min="1" max="60" value={probe.timeoutSeconds} onChange={(event) => setProbes((current) => current.map((item) => item.id === probe.id ? { ...item, timeoutSeconds: Number(event.target.value) } : item))} /></label><button className="icon-button" onClick={() => setProbes((current) => current.filter((item) => item.id !== probe.id))} aria-label="Remove health probe"><Trash2 /></button></div>)}<Button variant="secondary" icon={Plus} onClick={() => setProbes((current) => [...current, { id: id(), kind: "container", target: "app", timeoutSeconds: 30 }])}>Add health probe</Button></div></> : null}
      {step === 5 ? <><h2>Review immutable version</h2><p>The server will normalize the Compose file and enforce every restriction before persisting this version.</p><DefinitionList items={[["Package", name], ["Version", version], ["Compose", `${composeYaml.split("\n").length} lines`], ["Typed inputs", String(inputs.length)], ["Secret file targets", String(secrets.length)], ["Required roles", manifest.placement.requiredRoles.join(", ") || "Any"], ["Endpoints", endpoints.map((endpoint) => `${endpoint.name} · ${endpoint.protocol}/${endpoint.port} · ${endpoint.scope}`).join("; ") || "None"], ["Health probes", String(probes.length)]]} />{draftWorkloadId ? <IssueBanner tone="warning" title="Package record already exists">A previous version attempt failed after the package was created. Retry will publish into that same package without creating a duplicate.</IssueBanner> : null}</> : null}
      {publishError ? <IssueBanner tone="danger" title="Workload could not be published">{publishError}</IssueBanner> : null}
    </div><footer className="form-footer"><Button variant="quiet" onClick={() => step === 1 ? navigate("/workloads") : setStep(step - 1)}>{step === 1 ? "Cancel" : "Back"}</Button>{step < 5 ? <Button disabled={!stepValid} onClick={next}>Continue <ArrowRight /></Button> : <Button disabled={publishing} onClick={publish}>{publishing ? "Validating…" : "Validate and publish"} <ArrowRight /></Button>}</footer></section></> : <section className="waiting-card"><span className="success-orb"><Check /></span><h2>Version {version} published</h2><p>The immutable package digest is <code>sha256:{published.digest.slice(0, 6)}…{published.digest.slice(-4)}</code>.</p><Button onClick={() => navigate(`/workloads/${published.workloadId}`)}>View workload</Button></section>}
  </div>;
}

export function WorkloadDetailPage() { const { workloadId = "" } = useParams(); const packages = useQuery({ queryKey: ["workloads"], queryFn: listWorkloads, enabled: !demoMode }); const versions = useQuery({ queryKey: ["workload-versions", workloadId], queryFn: () => listWorkloadVersions(workloadId), enabled: !demoMode }); const demoItem = workloadCatalog.find((x) => x.id === workloadId) ?? workloadCatalog[0]; const item = demoMode ? demoItem : packages.data?.find(({ id }) => id === workloadId); const versionItems = demoMode ? [{ id: "demo-1", version: demoItem.latest, digest: "4f13d3fbd0238ac2", createdAt: new Date(Date.now() - 2 * 86400000).toISOString(), manifest: { endpoints: [{ scope: "public", protocol: "tcp", port: 443 }], probes: [{ kind: "http" }] } }, { id: "demo-2", version: "2.3.0", digest: "93b2a9bb12031c40", createdAt: new Date(Date.now() - 10 * 86400000).toISOString(), manifest: { endpoints: [], probes: [] } }] : versions.data ?? []; if (packages.isLoading || versions.isLoading) return <div className="page"><Skeleton rows={8} /></div>; if (!item || packages.error || versions.error) return <div className="page"><IssueBanner tone="danger" title="Workload could not be loaded">{packages.error instanceof Error ? packages.error.message : versions.error instanceof Error ? versions.error.message : "The workload does not exist."}</IssueBanner></div>; const latest = versionItems[0]; return <div className="page"><Link to="/workloads" className="back-link"><ArrowLeft /> Workloads</Link><PageHeader title={item.name} description={item.description} action={<StatusBadge tone={versionItems.length ? "success" : "neutral"}>{versionItems.length ? "Ready" : "No versions"}</StatusBadge>} /><div className="two-column two-column--detail"><section><SectionHeader title="Versions" detail="Published versions are immutable" />{versionItems.length ? <div className="resource-list">{versionItems.map((version, index) => <div className="resource-list__row resource-list__row--version" key={version.id}><span className="resource-avatar"><Box /></span><span className="resource-list__name"><strong>{version.version}</strong><small>sha256:{version.digest.slice(0, 4)}…{version.digest.slice(-4)}</small></span><StatusBadge tone={index === 0 ? "success" : "neutral"}>{index === 0 ? "Latest" : "Published"}</StatusBadge></div>)}</div> : <EmptyState title="No versions published" detail="Import an immutable version before adding this workload to an environment." />}</section><aside><SectionHeader title="Latest version" />{latest ? <section className="panel"><DefinitionList items={[["Published", relativeTime(latest.createdAt)], ["Public endpoints", String(latest.manifest.endpoints.filter((endpoint) => endpoint.scope === "public").length)], ["Health probes", `${latest.manifest.probes.length} configured`], ["Digest", <code>{latest.digest.slice(0, 12)}…</code>]]} /></section> : null}<IssueBanner tone="info" title="Restricted runtime">Every version is validated against the restricted Compose policy before publishing.</IssueBanner></aside></div></div>; }

export function ConnectionsPage() {
  const queryClient = useQueryClient(); const query = useQuery({ queryKey: ["connections"], queryFn: listConnections, enabled: !demoMode }); const [demoSaved, setDemoSaved] = useState<Array<{ id: string; name: string; accountId: string; validatedAt: string; partition: string; principalArn: string }>>([]); const demoConnections = [{ id: "demo-connection", name: "infra-production", accountId: "071234567890", validatedAt: new Date(Date.now() - 18 * 60_000).toISOString(), partition: "aws", principalArn: "demo" }, ...demoSaved]; const items = demoMode ? demoConnections : query.data ?? [];
  const [showSetup, setShowSetup] = useState(false); const [setupMode, setSetupMode] = useState<"create" | "revalidate">("create"); const [connectionName, setConnectionName] = useState(""); const [validating, setValidating] = useState(false); const [saving, setSaving] = useState(false); const [validation, setValidation] = useState<{ accountId: string; partition: string; principalArn: string; validatedAt: string } | null>(null); const [validationError, setValidationError] = useState<string | null>(null); const [saveError, setSaveError] = useState<string | null>(null); const [savedMessage, setSavedMessage] = useState<string | null>(null);
  const validate = async () => { setValidating(true); setValidationError(null); setValidation(null); try { setValidation(await validateAwsConnection()); } catch (error) { setValidationError(error instanceof ApiError ? error.detail ?? error.message : "AWS credentials could not be validated."); } finally { setValidating(false); } };
  const save = async () => { if (!validation || !connectionName.trim()) return; setSaving(true); setSaveError(null); try { const saved = await createAwsConnection(connectionName.trim()); if (demoMode) setDemoSaved((current) => [...current, saved]); else await queryClient.invalidateQueries({ queryKey: ["connections"] }); setSavedMessage(`${saved.name} is ready for environment plans.`); setShowSetup(false); setConnectionName(""); setValidation(null); } catch (error) { setSaveError(error instanceof ApiError ? error.detail ?? error.message : "The connection could not be saved."); } finally { setSaving(false); } };
  const openCreate = () => { setSetupMode("create"); setConnectionName(""); setValidation(null); setValidationError(null); setSaveError(null); setShowSetup(true); setSavedMessage(null); };
  return <div className="page"><PageHeader title="Connections" description="External accounts available to environment plans. Credentials stay in the worker credential chain." action={<Button icon={Plus} onClick={openCreate}>Add connection</Button>} />
    {showSetup ? <section className="connection-setup"><div className="section-header"><div><h2>{setupMode === "create" ? "Add AWS connection" : `Validate ${connectionName}`}</h2><p>{setupMode === "create" ? "Validate the worker's current credential chain before saving account metadata." : "Confirm that the worker still resolves to the expected AWS identity. This does not alter the saved record."}</p></div><button className="icon-button" onClick={() => setShowSetup(false)} aria-label="Close connection setup"><XCircle /></button></div><div className="connection-setup__form">{setupMode === "create" ? <label className="field"><span>Connection name</span><input value={connectionName} onChange={(event) => setConnectionName(event.target.value)} placeholder="infra-production" /></label> : <div />}<Button variant="secondary" icon={RefreshCw} onClick={validate} disabled={validating}>{validating ? "Validating…" : validation ? "Validate again" : "Validate credentials"}</Button></div>{validation ? <div className="validation-result"><span className="success-orb"><Check /></span><DefinitionList items={[["AWS account", validation.accountId], ["Partition", validation.partition], ["Principal", <code>{validation.principalArn}</code>], ["Validated", new Date(validation.validatedAt).toLocaleString()]]} />{setupMode === "create" ? <Button onClick={save} disabled={saving || !connectionName.trim()}>{saving ? "Saving…" : "Save connection"}</Button> : <Button onClick={() => setShowSetup(false)}>Done</Button>}</div> : null}{validationError ? <IssueBanner tone="danger" title="Validation failed">{validationError}</IssueBanner> : null}{saveError ? <IssueBanner tone="danger" title="Connection could not be saved">{saveError}</IssueBanner> : null}</section> : null}
    {savedMessage ? <IssueBanner tone="info" title="Connection saved">{savedMessage}</IssueBanner> : null}
    {query.error ? <IssueBanner tone="danger" title="Connections could not be loaded">{query.error instanceof Error ? query.error.message : "Connections are unavailable."}</IssueBanner> : query.isLoading && !demoMode ? <Skeleton rows={5} /> : items.length === 0 ? <EmptyState icon={Cloud} title="No AWS connection saved" detail="Add a connection to validate the worker credential chain and save its account metadata." action={<Button icon={Plus} onClick={openCreate}>Add AWS connection</Button>} /> : items.map((item) => <div className="connection-card" key={item.id}><span className="connection-logo"><Cloud /></span><div className="connection-main"><div><h2>{item.name}</h2><StatusBadge tone="success">Validated</StatusBadge></div><p>Amazon Web Services · account <span className="mono">{item.accountId}</span></p><footer><span>{item.partition}</span><span>Validated {relativeTime(item.validatedAt)}</span></footer></div><Button variant="secondary" icon={RefreshCw} onClick={() => { setSetupMode("revalidate"); setShowSetup(true); setConnectionName(item.name); setValidation(null); setValidationError(null); void validate(); }} disabled={validating}>{validating ? "Validating…" : "Validate chain"}</Button></div>)}<IssueBanner tone="info" title="No AWS keys are stored">The worker uses the standard AWS credential chain. Connection records contain validated account metadata only.</IssueBanner></div>;
}

export function ActivityPage() { return <div className="page"><PageHeader title="Activity" description="A durable history of operations and meaningful state changes." />{demoMode ? <><div className="toolbar"><label className="search-field"><Search /><input placeholder="Search activity" aria-label="Search activity" /></label></div><ActivityList /></> : <EmptyState icon={Icons.Activity} title="No activity reported" detail="Durable operation events will appear here when the control plane exposes its activity feed." />}</div>; }

export function SettingsPage() {
  const initial = (localStorage.getItem("infractory-theme") as "system" | "light" | "dark" | null) ?? "system"; const [theme, setTheme] = useState(initial);
  const chooseTheme = (value: "system" | "light" | "dark") => { setTheme(value); localStorage.setItem("infractory-theme", value); const dark = value === "dark" || (value === "system" && matchMedia("(prefers-color-scheme: dark)").matches); document.documentElement.dataset.theme = dark ? "dark" : "light"; document.documentElement.style.colorScheme = dark ? "dark" : "light"; dispatchEvent(new CustomEvent("infractory-theme-change", { detail: value })); };
  return <div className="page page--wide"><PageHeader title="Settings" description="Local presentation preferences and fixed control-plane behavior." /><div className="settings-layout"><nav className="settings-nav"><a className="active" href="#appearance">Appearance</a><a href="#operations">Operations</a><a href="#diagnostics">Diagnostics</a></nav><div><section className="settings-panel" id="appearance"><h2>Appearance</h2><p>Theme is stored on this device and applied before the interface renders.</p><div className="theme-options"><label><input type="radio" name="theme-preview" checked={theme === "system"} onChange={() => chooseTheme("system")} /><span className="theme-swatch theme-swatch--system" /><strong>System</strong></label><label><input type="radio" name="theme-preview" checked={theme === "light"} onChange={() => chooseTheme("light")} /><span className="theme-swatch theme-swatch--light" /><strong>Light</strong></label><label><input type="radio" name="theme-preview" checked={theme === "dark"} onChange={() => chooseTheme("dark")} /><span className="theme-swatch theme-swatch--dark" /><strong>Dark</strong></label></div></section><section className="settings-panel" id="operations"><h2>Operation guarantees</h2><DefinitionList items={[["Infrastructure changes", "Require a fresh, reviewed plan"], ["External mutations", "Persisted as durable operations"], ["Node heartbeat", "Every 15 seconds"], ["Full observation", "Every 60 seconds"]]} /><p className="settings-note">These safeguards are product invariants in this release, not editable preferences.</p></section><section className="settings-panel" id="diagnostics"><h2>Control-plane diagnostics</h2><p>Readiness and component health are reported by the deployment health endpoints. This console does not infer component health from the page loading successfully.</p></section></div></div></div>;
}

export function NotFoundPage() { return <div className="page"><EmptyState icon={Network} title="Page not found" detail="The address may be outdated, or the resource may no longer exist." action={<ButtonLink to="/environments">Go to environments</ButtonLink>} /></div>; }
